arguments.file_text:
@page "/chat"
@using sv_0a6ecd2917b14e6587385b85c1a17dd8.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <div class="channel-header">
                <h5># @_activeChannel.Name</h5>
                <span class="channel-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var msg in _messages)
                {
                    <MessageItem Message="msg"
                                 ReplyCount="GetReplyCount(msg.Id)"
                                 OnOpenThread="OpenThread"
                                 OnReact="HandleReaction" />
                }
            </div>

            <MessageInput Placeholder="@($"Message # {_activeChannel.Name}")"
                          OnSubmit="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply"
                         OnReact="HandleReaction" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadReplies = [];
    private Dictionary<int, int> _replyCounts = new();

    private Channel? _activeChannel;
    private int _activeChannelId;
    private Message? _threadRootMessage;
    private bool _threadOpen;
    private bool _loadingMore;
    private int _skip;
    private bool _hasMoreMessages = true;
    private const int PageSize = 30;

    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _skip = 0;
        _hasMoreMessages = true;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _skip = _messages.Count;
        await ChatService.MarkChannelReadAsync(channelId);
        BuildReplyCounts();
        CloseThread();
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages.
        // The JS-free approach: we rely on the event firing and check state.
        if (_loadingMore || !_hasMoreMessages) return;
        await LoadOlderMessages();
    }

    private async Task LoadOlderMessages()
    {
        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _skip, PageSize);
        if (older.Count < PageSize)
        {
            _hasMoreMessages = false;
        }

        _messages.InsertRange(0, older);
        _skip += older.Count;
        BuildReplyCounts();
        _loadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
        _skip++;
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(
            _activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update reply count
        _replyCounts[_threadRootMessage.Id] =
            _replyCounts.GetValueOrDefault(_threadRootMessage.Id) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect updated reaction counts
        if (_activeChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _skip);
        }
        if (_threadOpen && _threadRootMessage is not null)
        {
            _threadReplies = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        }
    }

    private void BuildReplyCounts()
    {
        _replyCounts.Clear();
        foreach (var msg in _messages.Where(m => m.ReplyToId is not null))
        {
            var rootId = msg.ReplyToId!.Value;
            _replyCounts[rootId] = _replyCounts.GetValueOrDefault(rootId) + 1;
        }
    }

    private int GetReplyCount(int messageId) =>
        _replyCounts.GetValueOrDefault(messageId);
}

.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    background-color: #313338;
    color: #dcddde;
    overflow: hidden;
}

